import React, { useState } from 'react';


const Handling = () => {
  const [message, setMessage] = useState('Hello');
  const handleClickMessage = (event) => {
    setMessage('Hello');
  }


  return (
    <div>
      <h1>Handling</h1>

      <button onClick={handleClickMessage}>Click</button>
    </div>
  );
};

export default Handling;
